<?=form_open('weighted_exam/grades')?><section class="panel"><header class="panel-heading"><h4 class="panel-title">Configurable Result Categories</h4></header><div class="panel-body"><div class="alert alert-info">Ranges should cover 0–100 without overlaps. A result with no matching range is marked incomplete.</div><div class="table-responsive"><table class="table table-bordered" id="gradeRules"><thead><tr><th>Name</th><th>Minimum %</th><th>Maximum %</th><th>Pass</th></tr></thead><tbody><?php $display=$rules?:[['name'=>'Distinction','minimum_percentage'=>80,'maximum_percentage'=>100,'is_pass'=>1],['name'=>'First Division','minimum_percentage'=>60,'maximum_percentage'=>79.99,'is_pass'=>1],['name'=>'Second Division','minimum_percentage'=>45,'maximum_percentage'=>59.99,'is_pass'=>1],['name'=>'Pass','minimum_percentage'=>33,'maximum_percentage'=>44.99,'is_pass'=>1],['name'=>'Fail','minimum_percentage'=>0,'maximum_percentage'=>32.99,'is_pass'=>0]];foreach($display as $i=>$r):?><tr><td><input class="form-control" name="rules[<?=$i?>][name]" value="<?=html_escape($r['name'])?>"></td><td><input type="number" step="0.01" min="0" max="100" class="form-control" name="rules[<?=$i?>][min]" value="<?=$r['minimum_percentage']?>"></td><td><input type="number" step="0.01" min="0" max="100" class="form-control" name="rules[<?=$i?>][max]" value="<?=$r['maximum_percentage']?>"></td><td><input type="checkbox" name="rules[<?=$i?>][pass]" value="1" <?=$r['is_pass']?'checked':''?>></td></tr><?php endforeach?></tbody></table></div></div><footer class="panel-footer text-right"><button name="save" value="1" class="btn btn-default"><i class="fas fa-save"></i> Save Rules</button></footer></section><?=form_close()?>
